Here's an example C++ program that reads a text file line by line and counts the number of occurrences of a specific word in the file:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>

using namespace std;

int main() {
    string word;
    int count = 0;

    // Prompt user for file name and word to search for
    cout << "Enter file name: ";
    string fileName;
    getline(cin, fileName);
    cout << "Enter word to search for: ";
    getline(cin, word);

    // Open file and read lines
    ifstream file(fileName);
    if (!file.is_open()) {
        cout << "Error opening file." << endl;
        return 1;
    }
    string line;
    while (getline(file, line)) {
        // Split line into words
        vector<string> words;
        string word;
        for (int I = 0; I < line.length(); i++) {
            if (line[i] == ' ') {
                words.push_back(word);
                word = "";
            } else {
                word += line[i];
            }
        }
        words.push_back(word);

        // Count occurrences of word
        for (int I = 0; I < words.size(); i++) {
            if (words[i] == word) {
                count++;
            }
        }
    }

    // Close file
    file.close();

    // Print result
    cout << "Word \"" << word << "\" appears " << count << " times in file \"" << fileName << "\"." << endl;

    return 0;
}
```

This program first prompts the user for the file name and the word to search for. It then opens the file and reads each line, splitting it into words using a simple algorithm. For each word, it checks if it matches the search word and increments the count if it does. Finally, it prints the result to the console.
